insert into public.illness_scripts (id, version, status, reviewed_by, reviewed_at, content) values
  ('zorblax-syndrome', 1, 'approved', 'TEST', '2026-11-13T00:00:00Z', '{"name":"Zorblax syndrome","aliases":["ZBX"],"rotation":["IM"],"epidemiology":{"who":"Fictional adults over 40 (test fixture, not a real disease)","risk_factors":["glimmer exposure","night shift work","low blorp diet","family history"]},"pathophysiology":"Fictional autoimmune attack on the glimmer gland.","timeline":{"onset":"Subacute, over weeks","course":"Relapsing-remitting"},"key_findings":{"history":["purple fatigue","itchy elbows"],"exam":["blue nail beds"],"labs":["high serum blorp"],"imaging":["swollen glimmer gland on ultrasound"]},"diagnosis":{"confirmatory_tests":["anti-glimmer antibody"],"criteria":["serum blorp above 40 units with blue nail beds"]},"management":{"first_line":["zorbicillin"],"next_line":["plasma swap"]},"complications":["glimmer storm"],"confused_with":[{"script_id":"quellan-fever","how_to_tell_apart":"Quellan fever causes green nail beds and a normal blorp."}],"pearls":["Zorblax syndrome never causes fever."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam[0]","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[{"kind":"note","id":"1000000001"}],"sources":[{"title":"Rounds test fixture (fictional)"}]}'::jsonb),
  ('quellan-fever', 1, 'approved', 'TEST', '2026-11-13T00:00:00Z', '{"name":"Quellan fever","aliases":["QF"],"rotation":["IM"],"epidemiology":{"who":"Fictional travelers (test fixture)","risk_factors":["quellan bites"]},"pathophysiology":"Fictional infection of the nail matrix.","timeline":{"onset":"Acute, over days","course":"Self-limited"},"key_findings":{"history":["fever","purple fatigue"],"exam":["green nail beds"],"labs":["normal blorp"],"imaging":[]},"diagnosis":{"confirmatory_tests":["quellan PCR"],"criteria":[]},"management":{"first_line":["supportive care"],"next_line":[]},"complications":[],"confused_with":[{"script_id":"zorblax-syndrome","how_to_tell_apart":"Zorblax syndrome causes blue nail beds, high blorp and no fever."}],"pearls":[],"difficulty_tiers":{"MS1-2":[],"MS3":["key_findings.exam[0]"],"MS4":[]},"anki_refs":[],"sources":[{"title":"Rounds test fixture (fictional)"}]}'::jsonb),
  ('acute-coronary-syndrome', 1, 'in_review', null, null, '{"name":"Acute coronary syndrome","aliases":["ACS","myocardial infarction"],"rotation":["IM","EM"],"epidemiology":{"who":"Adults with atherosclerotic risk factors","risk_factors":["smoking","diabetes","hypertension","hyperlipidemia","family history of premature coronary disease","older age"]},"pathophysiology":"Rupture or erosion of an atherosclerotic plaque triggers a thrombus that reduces or blocks coronary blood flow, causing myocardial ischemia or infarction.","timeline":{"onset":"Sudden, often at rest","course":"Heart muscle is lost with every minute of a complete occlusion"},"key_findings":{"history":["pressure-like chest pain radiating to the arm or jaw","dyspnea","diaphoresis","nausea"],"exam":["often normal","signs of heart failure or shock in large infarcts"],"labs":["rise and fall of high-sensitivity troponin","ECG: ST elevation in STEMI; ST depression or T-wave inversion in NSTE-ACS"],"imaging":["echocardiogram for wall motion abnormalities"]},"diagnosis":{"confirmatory_tests":["12-lead ECG within 10 minutes","high-sensitivity troponin, repeated"],"criteria":["STEMI: ST elevation in two contiguous leads","NSTEMI: troponin rise without ST elevation","unstable angina: ischemic symptoms without a troponin rise"]},"management":{"first_line":["aspirin","second antiplatelet agent (P2Y12 inhibitor such as ticagrelor)","anticoagulation with heparin","primary PCI within 90 minutes for STEMI"],"next_line":["fibrinolysis if PCI is not available within 120 minutes","high-intensity statin","beta-blocker if no heart failure or shock","nitroglycerin for ongoing pain"]},"complications":["arrhythmias","heart failure","cardiogenic shock","papillary muscle rupture","ventricular free wall rupture"],"confused_with":[{"script_id":"aortic-dissection","how_to_tell_apart":"Aortic dissection gives sudden tearing pain radiating to the back, a blood pressure difference between arms and a widened mediastinum; exclude it before giving anticoagulants."},{"script_id":"pulmonary-embolism","how_to_tell_apart":"PE causes pleuritic pain, hypoxemia and tachycardia, usually without ST elevation."}],"pearls":["Avoid nitrates in inferior MI with right ventricular involvement, or after a phosphodiesterase inhibitor such as sildenafil: they can cause severe hypotension."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"2025 ACC/AHA/ACEP/NAEMSP/SCAI Guideline for the Management of Patients With Acute Coronary Syndromes"}]}'::jsonb),
  ('acute-ischemic-stroke', 1, 'in_review', null, null, '{"name":"Acute ischemic stroke","aliases":["stroke","CVA"],"rotation":["IM","EM","neuro"],"epidemiology":{"who":"Older adults with vascular risk factors","risk_factors":["hypertension","atrial fibrillation","diabetes","smoking","hyperlipidemia","prior stroke or TIA"]},"pathophysiology":"A thrombus or embolus blocks a brain artery; the ischemic penumbra around the core can be saved by fast reperfusion.","timeline":{"onset":"Sudden","course":"Brain tissue is lost each minute until reperfusion"},"key_findings":{"history":["sudden one-sided weakness or numbness","speech difficulty","facial droop","time last known well"],"exam":["focal neurologic deficit matching a vascular territory","NIH Stroke Scale to grade severity"],"labs":["fingerstick glucose to exclude hypoglycemia"],"imaging":["noncontrast CT head to exclude hemorrhage","CT angiography to find a large vessel occlusion"]},"diagnosis":{"confirmatory_tests":["noncontrast CT head","CT angiography"],"criteria":["sudden focal deficit with a vascular explanation and no hemorrhage on imaging"]},"management":{"first_line":["IV thrombolysis (alteplase or tenecteplase) within 4.5 hours of last known well","mechanical thrombectomy for large vessel occlusion, up to 24 hours in selected patients","check glucose before treatment"],"next_line":["aspirin within 24 to 48 hours if not thrombolysed","secondary prevention: antiplatelet, statin, and anticoagulation for atrial fibrillation"]},"complications":["hemorrhagic transformation","cerebral edema","aspiration pneumonia","dysphagia"],"confused_with":[],"pearls":["Blood pressure must be below 185/110 mmHg before thrombolysis."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"Guidelines for the Early Management of Patients With Acute Ischemic Stroke: 2019 Update (AHA/ASA)"}]}'::jsonb),
  ('acute-kidney-injury', 1, 'in_review', null, null, '{"name":"Acute kidney injury","aliases":["AKI","acute renal failure"],"rotation":["IM"],"epidemiology":{"who":"Hospitalized adults, especially older patients and those with chronic kidney disease","risk_factors":["volume depletion","sepsis","nephrotoxic drugs","IV contrast","urinary obstruction","chronic kidney disease"]},"pathophysiology":"A sudden fall in glomerular filtration, classified as prerenal (low perfusion), intrinsic (most often acute tubular necrosis) or postrenal (obstruction).","timeline":{"onset":"Hours to days","course":"Often recovers once the cause is fixed; can progress to dialysis or chronic kidney disease"},"key_findings":{"history":["reduced urine output","recent vomiting, diarrhea or poor intake","new medications such as NSAIDs, ACE inhibitors or aminoglycosides"],"exam":["signs of volume depletion or overload","palpable bladder in obstruction"],"labs":["creatinine rise of 0.3 mg/dL or more within 48 hours","BUN-to-creatinine ratio above 20 in prerenal AKI","muddy brown granular casts in acute tubular necrosis","fractional excretion of sodium below 1% in prerenal AKI"],"imaging":["renal ultrasound to look for hydronephrosis"]},"diagnosis":{"confirmatory_tests":["serum creatinine","urine output","urinalysis with microscopy","renal ultrasound"],"criteria":["creatinine rise of 0.3 mg/dL or more within 48 hours","creatinine 1.5 times baseline or more within 7 days","urine output below 0.5 mL/kg/h for 6 hours"]},"management":{"first_line":["treat the cause","IV fluids if volume depleted","stop nephrotoxic drugs","relieve obstruction"],"next_line":["dialysis for refractory hyperkalemia, acidosis, volume overload, uremic complications or toxins","adjust drug doses for kidney function"]},"complications":["hyperkalemia","metabolic acidosis","volume overload","uremic pericarditis","progression to chronic kidney disease"],"confused_with":[],"pearls":["Indications for urgent dialysis (AEIOU): acidosis, electrolytes (hyperkalemia), ingestions, overload and uremia."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"KDIGO Clinical Practice Guideline for Acute Kidney Injury (2012)"}]}'::jsonb),
  ('acute-pancreatitis', 1, 'in_review', null, null, '{"name":"Acute pancreatitis","aliases":[],"rotation":["IM","surgery"],"epidemiology":{"who":"Adults; gallstones are the most common cause, then heavy alcohol use","risk_factors":["gallstones","alcohol","hypertriglyceridemia","post-ERCP","medications","hypercalcemia"]},"pathophysiology":"Premature activation of pancreatic enzymes (trypsin) inside the gland causes autodigestion and local inflammation, which can become a systemic inflammatory response.","timeline":{"onset":"Sudden, over hours","course":"Mild disease settles within a week; severe disease brings organ failure lasting over 48 hours and local complications"},"key_findings":{"history":["sudden epigastric pain radiating to the back","nausea and vomiting","recent heavy alcohol use or known gallstones"],"exam":["epigastric tenderness","tachycardia","flank or periumbilical bruising in severe disease"],"labs":["lipase more than 3 times the upper limit of normal","raised ALT in gallstone pancreatitis"],"imaging":["right upper quadrant ultrasound to look for gallstones","contrast CT only if the diagnosis is unclear or the patient is not improving"]},"diagnosis":{"confirmatory_tests":["serum lipase","right upper quadrant ultrasound"],"criteria":["two of three: typical epigastric pain, lipase more than 3 times the upper limit of normal, characteristic imaging findings"]},"management":{"first_line":["early goal-directed IV fluids with lactated Ringer''s","pain control","early oral feeding as tolerated"],"next_line":["cholecystectomy during the same admission for mild gallstone pancreatitis","ERCP within 24 hours if there is cholangitis","no prophylactic antibiotics"]},"complications":["pancreatic pseudocyst","walled-off necrosis","infected necrosis","ARDS","acute kidney injury"],"confused_with":[{"script_id":"diabetic-ketoacidosis","how_to_tell_apart":"DKA can cause abdominal pain and a mildly raised lipase, but it has high glucose, ketones and an anion gap acidosis, and the pain improves as the acidosis is treated."}],"pearls":["Gallstone pancreatitis is suggested by an ALT more than 3 times the upper limit of normal."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.history[0]","diagnosis.criteria[0]","management.first_line"],"MS4":["pearls[0]","management.next_line[0]"]},"anki_refs":[],"sources":[{"title":"American College of Gastroenterology Guideline: Management of Acute Pancreatitis (2024)"},{"title":"Classification of acute pancreatitis: revision of the Atlanta classification by international consensus (2012)"}]}'::jsonb),
  ('acute-pyelonephritis', 1, 'in_review', null, null, '{"name":"Acute pyelonephritis","aliases":["pyelonephritis","kidney infection"],"rotation":["IM","EM","FM"],"epidemiology":{"who":"Mostly women; also men with urinary obstruction","risk_factors":["female sex","recent sexual intercourse","urinary obstruction or stones","pregnancy","diabetes","urinary catheter"]},"pathophysiology":"Bacteria, most often Escherichia coli, ascend from the bladder and infect the kidney.","timeline":{"onset":"Over 1 to 2 days","course":"Fever usually settles within 72 hours of antibiotics"},"key_findings":{"history":["fever and chills","flank pain","dysuria and frequency","nausea and vomiting"],"exam":["costovertebral angle tenderness","fever"],"labs":["pyuria","white blood cell casts","positive urine culture"],"imaging":["CT or ultrasound if there is no improvement after 48 to 72 hours, or obstruction is suspected"]},"diagnosis":{"confirmatory_tests":["urinalysis","urine culture before antibiotics"],"criteria":["flank pain or costovertebral angle tenderness with fever and pyuria"]},"management":{"first_line":["oral fluoroquinolone (ciprofloxacin) if local resistance is low and the patient is well","IV ceftriaxone if admitted"],"next_line":["tailor to culture results","imaging and drainage for obstruction or abscess"]},"complications":["sepsis","renal abscess","emphysematous pyelonephritis"],"confused_with":[],"pearls":["White blood cell casts in the urine point to the kidney (pyelonephritis) rather than the bladder."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"International Clinical Practice Guidelines for the Treatment of Acute Uncomplicated Cystitis and Pyelonephritis in Women (IDSA and ESCMID, 2010)"}]}'::jsonb),
  ('adrenal-insufficiency', 1, 'in_review', null, null, '{"name":"Adrenal insufficiency","aliases":["Addison disease","adrenal crisis"],"rotation":["IM"],"epidemiology":{"who":"Primary disease is usually autoimmune; secondary disease most often follows stopping long-term glucocorticoids","risk_factors":["autoimmune adrenalitis","abrupt withdrawal of long-term steroids","tuberculosis","adrenal hemorrhage","pituitary disease"]},"pathophysiology":"Primary disease destroys the adrenal cortex, losing cortisol and aldosterone; secondary disease lacks ACTH, losing cortisol only.","timeline":{"onset":"Insidious, or a sudden crisis during illness","course":"Needs lifelong replacement; a crisis is fatal without steroids"},"key_findings":{"history":["fatigue and weakness","weight loss","nausea, vomiting and abdominal pain","salt craving"],"exam":["hypotension","hyperpigmentation of skin and gums in primary disease"],"labs":["hyponatremia","hyperkalemia in primary disease","low morning cortisol","hypoglycemia"],"imaging":[]},"diagnosis":{"confirmatory_tests":["morning serum cortisol","ACTH stimulation test (cosyntropin)","plasma ACTH to separate primary from secondary disease"],"criteria":["a peak cortisol below 18 micrograms/dL after cosyntropin confirms adrenal insufficiency"]},"management":{"first_line":["adrenal crisis: IV hydrocortisone 100 mg and IV saline immediately","chronic: hydrocortisone replacement","fludrocortisone in primary disease"],"next_line":["double the steroid dose during illness (sick-day rules)","medical alert identification and an emergency injection kit"]},"complications":["adrenal crisis","shock","death"],"confused_with":[{"script_id":"septic-shock","how_to_tell_apart":"Septic shock also causes fluid-resistant hypotension with fever; adrenal crisis adds hyponatremia, hyperkalemia and hypoglycemia, and responds to hydrocortisone."}],"pearls":["Hyperkalemia and hyperpigmentation point to primary disease; in secondary disease aldosterone is intact and ACTH is low."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"Diagnosis and Treatment of Primary Adrenal Insufficiency: An Endocrine Society Clinical Practice Guideline (2016)"}]}'::jsonb),
  ('alcohol-withdrawal', 1, 'in_review', null, null, '{"name":"Alcohol withdrawal","aliases":["alcohol withdrawal syndrome","delirium tremens"],"rotation":["IM","EM","psych"],"epidemiology":{"who":"People who drink heavily every day and stop or cut down, often on hospital admission","risk_factors":["heavy daily drinking","prior withdrawal seizures or delirium tremens","sudden abstinence","older age","acute medical illness"]},"pathophysiology":"Chronic alcohol enhances GABA and suppresses glutamate signalling; stopping leaves unopposed excitation.","timeline":{"onset":"Tremor from about 6 hours; seizures at 12 to 48 hours; delirium tremens at 48 to 96 hours","course":"Delirium tremens can be fatal"},"key_findings":{"history":["time of the last drink","tremor","anxiety","sweating","hallucinations"],"exam":["tremor","tachycardia","hypertension","diaphoresis","agitation or confusion in delirium tremens"],"labs":["hypokalemia","hypomagnesemia","hypophosphatemia","raised GGT","macrocytosis"],"imaging":[]},"diagnosis":{"confirmatory_tests":["clinical diagnosis","CIWA-Ar score to grade severity"],"criteria":["withdrawal symptoms after stopping or reducing heavy, prolonged drinking"]},"management":{"first_line":["benzodiazepines such as lorazepam or chlordiazepoxide, symptom-triggered by CIWA-Ar","thiamine before glucose","correct magnesium and potassium"],"next_line":["phenobarbital for benzodiazepine-resistant withdrawal","ICU for delirium tremens"]},"complications":["withdrawal seizures","delirium tremens","Wernicke encephalopathy","death"],"confused_with":[],"pearls":["Give thiamine before glucose in heavy drinkers to avoid precipitating Wernicke encephalopathy."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"The ASAM Clinical Practice Guideline on Alcohol Withdrawal Management (2020)"}]}'::jsonb),
  ('aortic-dissection', 1, 'in_review', null, null, '{"name":"Aortic dissection","aliases":["dissecting aorta"],"rotation":["IM","EM","surgery"],"epidemiology":{"who":"Older adults with hypertension; younger patients with connective tissue disease","risk_factors":["hypertension","Marfan syndrome","bicuspid aortic valve","cocaine use","prior aortic surgery","pregnancy"]},"pathophysiology":"A tear in the aortic intima lets blood split the media, creating a false lumen that can extend, block branch arteries or rupture.","timeline":{"onset":"Sudden","course":"Type A (ascending aorta) is a surgical emergency with high early mortality"},"key_findings":{"history":["sudden severe tearing chest pain radiating to the back","syncope","stroke-like symptoms"],"exam":["blood pressure difference of more than 20 mmHg between arms","pulse deficit","new murmur of aortic regurgitation"],"labs":["D-dimer usually raised"],"imaging":["widened mediastinum on chest X-ray","CT angiography of the chest showing an intimal flap"]},"diagnosis":{"confirmatory_tests":["CT angiography of the chest","transesophageal echocardiogram if unstable"],"criteria":["Stanford type A involves the ascending aorta; type B does not"]},"management":{"first_line":["IV beta-blocker such as esmolol to lower heart rate and blood pressure","pain control","emergency surgery for type A"],"next_line":["add a vasodilator such as nicardipine after beta-blockade","medical management for uncomplicated type B","endovascular repair for complicated type B"]},"complications":["aortic rupture","cardiac tamponade","acute aortic regurgitation","stroke","mesenteric or limb ischemia"],"confused_with":[{"script_id":"acute-coronary-syndrome","how_to_tell_apart":"ACS gives pressure-like pain with ECG changes and a troponin rise; dissection gives tearing pain to the back, unequal arm pressures and a widened mediastinum, and anticoagulation can be fatal."}],"pearls":["Give the beta-blocker before any vasodilator: lowering blood pressure alone causes reflex tachycardia that increases shear on the aorta."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"2022 ACC/AHA Guideline for the Diagnosis and Management of Aortic Disease"}]}'::jsonb),
  ('asthma-exacerbation', 1, 'in_review', null, null, '{"name":"Asthma exacerbation","aliases":["acute asthma","asthma attack"],"rotation":["IM","EM","peds"],"epidemiology":{"who":"Children and adults with asthma, especially with poor control or prior severe attacks","risk_factors":["viral respiratory infection","allergen exposure","poor adherence to inhaled steroids","smoke exposure","exercise","cold air"]},"pathophysiology":"Airway inflammation, bronchospasm and mucus plugging cause reversible airflow obstruction and air trapping.","timeline":{"onset":"Over hours to days","course":"Usually responds to treatment; severe attacks can progress to respiratory failure"},"key_findings":{"history":["dyspnea","wheeze","chest tightness","cough, often worse at night"],"exam":["expiratory wheeze","tachypnea","accessory muscle use","silent chest in life-threatening attacks"],"labs":["peak expiratory flow below 50% of predicted in a severe attack","a normal or rising PaCO2 is a warning sign of fatigue"],"imaging":["chest X-ray only if pneumothorax or pneumonia is suspected"]},"diagnosis":{"confirmatory_tests":["peak expiratory flow","pulse oximetry","arterial blood gas in severe attacks"],"criteria":["acute worsening of symptoms and lung function from the patient''s usual status"]},"management":{"first_line":["inhaled short-acting beta-agonist (albuterol), repeated","systemic corticosteroids","oxygen to keep saturation 93 to 95%","ipratropium in severe attacks"],"next_line":["IV magnesium sulfate for severe attacks","ICU and intubation for respiratory failure"]},"complications":["respiratory failure","pneumothorax","death"],"confused_with":[{"script_id":"copd-exacerbation","how_to_tell_apart":"COPD affects older smokers, and its airflow limitation persists between exacerbations; in asthma it is largely reversible."}],"pearls":["A normal or rising PaCO2 during an asthma attack means the patient is tiring and may need intubation."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"Global Strategy for Asthma Management and Prevention (GINA 2024)"}]}'::jsonb),
  ('atrial-fibrillation', 1, 'in_review', null, null, '{"name":"Atrial fibrillation","aliases":["AF","AFib"],"rotation":["IM","EM","FM"],"epidemiology":{"who":"Mostly older adults; prevalence rises sharply with age","risk_factors":["older age","hypertension","heart failure","valvular heart disease","obesity","obstructive sleep apnea","alcohol","hyperthyroidism"]},"pathophysiology":"Disorganized atrial electrical activity, often triggered from the pulmonary veins, causes loss of atrial contraction and an irregular ventricular response; stasis in the left atrial appendage lets clot form and embolize.","timeline":{"onset":"Sudden or unnoticed","course":"Often starts paroxysmal and becomes persistent or permanent over time"},"key_findings":{"history":["palpitations","dyspnea","fatigue","lightheadedness","sometimes no symptoms"],"exam":["irregularly irregular pulse","variable intensity of S1"],"labs":["TSH to look for hyperthyroidism"],"imaging":["echocardiogram for chamber size, valves and ejection fraction"]},"diagnosis":{"confirmatory_tests":["12-lead ECG"],"criteria":["ECG: irregularly irregular rhythm with no discernible P waves"]},"management":{"first_line":["rate control with a beta-blocker or a nondihydropyridine calcium channel blocker","anticoagulation based on stroke risk (CHA2DS2-VASc)","synchronized cardioversion if hemodynamically unstable"],"next_line":["rhythm control with cardioversion, antiarrhythmic drugs or catheter ablation","if AF has lasted 48 hours or more or the duration is unknown, anticoagulate for 3 weeks before elective cardioversion or exclude clot with a transesophageal echocardiogram"]},"complications":["ischemic stroke","systemic embolism","tachycardia-induced cardiomyopathy","heart failure"],"confused_with":[],"pearls":["Direct oral anticoagulants are preferred over warfarin, except with a mechanical heart valve or moderate to severe mitral stenosis."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.criteria[0]","management.first_line"],"MS4":["pearls[0]","management.next_line[1]"]},"anki_refs":[],"sources":[{"title":"2023 ACC/AHA/ACCP/HRS Guideline for the Diagnosis and Management of Atrial Fibrillation"}]}'::jsonb),
  ('bacterial-meningitis', 1, 'in_review', null, null, '{"name":"Bacterial meningitis","aliases":["meningitis"],"rotation":["IM","EM","peds","neuro"],"epidemiology":{"who":"Infants, older adults and the immunocompromised; outbreaks in college dormitories","risk_factors":["age over 50","immunosuppression","asplenia","cochlear implant","CSF leak","crowded living such as dormitories"]},"pathophysiology":"Bacteria, most often Streptococcus pneumoniae or Neisseria meningitidis in adults, invade the subarachnoid space and inflame the meninges.","timeline":{"onset":"Hours to a day","course":"Fatal without prompt antibiotics; survivors may have hearing loss or neurologic deficits"},"key_findings":{"history":["fever","headache","neck stiffness","confusion"],"exam":["nuchal rigidity","altered mental status","petechial or purpuric rash in meningococcal disease","Kernig and Brudzinski signs, which are insensitive"],"labs":["CSF: high neutrophils, high protein, low glucose","CSF Gram stain and culture"],"imaging":["CT head before lumbar puncture only with focal deficits, papilledema, seizures, reduced consciousness or immunocompromise"]},"diagnosis":{"confirmatory_tests":["lumbar puncture with CSF analysis","blood cultures"],"criteria":["CSF neutrophilic pleocytosis with low glucose and high protein"]},"management":{"first_line":["empiric ceftriaxone plus vancomycin","add ampicillin if over 50 or immunocompromised (to cover Listeria)","dexamethasone before or with the first antibiotic dose"],"next_line":["droplet precautions and prophylaxis for close contacts in meningococcal disease","tailor antibiotics to culture"]},"complications":["hearing loss","seizures","cerebral edema","death"],"confused_with":[],"pearls":["Never delay antibiotics for a CT or lumbar puncture: take blood cultures and treat immediately."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"2016 ESCMID guideline: diagnosis and treatment of acute bacterial meningitis"},{"title":"IDSA Practice Guidelines for the Management of Bacterial Meningitis (2004)"}]}'::jsonb),
  ('cellulitis', 1, 'in_review', null, null, '{"name":"Cellulitis","aliases":[],"rotation":["IM","EM","FM"],"epidemiology":{"who":"Adults with breaks in the skin barrier, leg edema or obesity","risk_factors":["skin breaks such as cuts or tinea pedis","lymphedema","obesity","venous insufficiency","prior cellulitis","diabetes"]},"pathophysiology":"Bacterial infection of the dermis and subcutaneous tissue, most often from beta-hemolytic streptococci and less often from Staphylococcus aureus.","timeline":{"onset":"Over 1 to 3 days","course":"Improves within 48 to 72 hours of antibiotics"},"key_findings":{"history":["spreading redness","pain","fever in some"],"exam":["warm, red, tender skin with poorly defined borders","usually one leg","no fluctuance unless there is an abscess"],"labs":["blood cultures only if systemically unwell"],"imaging":["ultrasound if an abscess is suspected"]},"diagnosis":{"confirmatory_tests":["clinical diagnosis"],"criteria":["acute spreading erythema, warmth and tenderness, usually on one side"]},"management":{"first_line":["oral cephalexin for nonpurulent cellulitis","elevate the limb","treat tinea pedis or other entry points"],"next_line":["add MRSA coverage (trimethoprim-sulfamethoxazole or doxycycline) for purulent infection","IV cefazolin if systemically ill","incision and drainage for an abscess"]},"complications":["abscess","bacteremia","necrotizing fasciitis","recurrence"],"confused_with":[{"script_id":"deep-vein-thrombosis","how_to_tell_apart":"DVT causes swelling and calf pain without spreading redness or fever, and compression ultrasound shows a clot."}],"pearls":["Redness of both legs is rarely cellulitis; think of stasis dermatitis first."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"Practice Guidelines for the Diagnosis and Management of Skin and Soft Tissue Infections: 2014 Update by the IDSA"}]}'::jsonb),
  ('clostridioides-difficile-infection', 1, 'in_review', null, null, '{"name":"Clostridioides difficile infection","aliases":["C. diff","CDI"],"rotation":["IM"],"epidemiology":{"who":"Hospitalized and older adults, especially after antibiotics","risk_factors":["recent antibiotics","hospitalization","older age","proton pump inhibitors","immunosuppression"]},"pathophysiology":"Antibiotics disrupt the gut flora, letting toxin-producing C. difficile colonize the colon and cause colitis.","timeline":{"onset":"Days to weeks after antibiotics","course":"About 1 in 5 recur after treatment"},"key_findings":{"history":["three or more watery stools in 24 hours","abdominal cramping","recent antibiotics, especially clindamycin, fluoroquinolones or cephalosporins"],"exam":["abdominal tenderness","fever"],"labs":["leukocytosis, sometimes very high","raised creatinine in severe disease"],"imaging":["CT for suspected fulminant colitis or toxic megacolon"]},"diagnosis":{"confirmatory_tests":["stool test for C. difficile toxin or toxin gene (PCR)"],"criteria":["test only unformed stool, from patients with 3 or more unexplained loose stools in 24 hours","severe: white count of 15,000 or more, or creatinine above 1.5 mg/dL"]},"management":{"first_line":["oral fidaxomicin or oral vancomycin","stop the inciting antibiotic if possible","contact precautions and soap-and-water hand hygiene"],"next_line":["fulminant disease: oral vancomycin plus IV metronidazole, and a surgical consult","recurrence: fidaxomicin, bezlotoxumab or fecal microbiota transplant"]},"complications":["toxic megacolon","colonic perforation","recurrence","death"],"confused_with":[],"pearls":["Alcohol hand rubs do not kill C. difficile spores; wash with soap and water."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"Clinical Practice Guideline by IDSA and SHEA: 2021 Focused Update Guidelines on Management of Clostridioides difficile Infection in Adults"}]}'::jsonb),
  ('community-acquired-pneumonia', 1, 'in_review', null, null, '{"name":"Community-acquired pneumonia","aliases":["CAP"],"rotation":["IM","EM","FM"],"epidemiology":{"who":"Adults living in the community; risk rises with age and chronic lung disease","risk_factors":["age 65 or older","smoking","COPD","alcohol use disorder","immunosuppression"]},"pathophysiology":"Infection of the lung parenchyma, usually after aspiration of upper airway organisms. Streptococcus pneumoniae is the most common cause; others include Haemophilus influenzae, Mycoplasma pneumoniae, respiratory viruses, Staphylococcus aureus and Legionella.","timeline":{"onset":"Acute, over a few days","course":"Most patients improve within 48 to 72 hours of appropriate antibiotics"},"key_findings":{"history":["fever","cough with sputum","pleuritic chest pain","dyspnea"],"exam":["focal crackles","bronchial breath sounds","dullness to percussion","tachypnea"],"labs":["leukocytosis","hypoxemia"],"imaging":["chest X-ray showing a new lobar or focal infiltrate"]},"diagnosis":{"confirmatory_tests":["chest X-ray"],"criteria":["compatible symptoms plus a new infiltrate on chest imaging"]},"management":{"first_line":["outpatient without comorbidities: amoxicillin or doxycycline (a macrolide only where pneumococcal macrolide resistance is below 25%)","outpatient with comorbidities: amoxicillin-clavulanate or a cephalosporin plus a macrolide or doxycycline, or a respiratory fluoroquinolone alone","inpatient, not severe: ceftriaxone plus azithromycin, or a respiratory fluoroquinolone alone"],"next_line":["add MRSA or Pseudomonas coverage only with prior isolation of those organisms or other validated risk factors","ICU admission for severe pneumonia"]},"complications":["parapneumonic effusion","empyema","sepsis","ARDS","lung abscess"],"confused_with":[{"script_id":"pulmonary-embolism","how_to_tell_apart":"Pulmonary embolism also causes pleuritic pain, dyspnea and tachycardia, but usually has clear lungs and a near-normal chest X-ray despite hypoxemia; suspect it when there are risk factors for clots."},{"script_id":"heart-failure-exacerbation","how_to_tell_apart":"Heart failure gives bilateral crackles, a raised JVP, leg edema and a high BNP, with bilateral interstitial edema and effusions on X-ray rather than a focal consolidation, and usually no fever."},{"script_id":"copd-exacerbation","how_to_tell_apart":"A COPD exacerbation brings more dyspnea and sputum in a known smoker, without a new consolidation on chest X-ray."}],"pearls":["CURB-65 (confusion, urea over 19 mg/dL, respiratory rate 30 or more, low blood pressure, age 65 or older) is a quick bedside guide to admission; the ATS/IDSA guideline prefers the Pneumonia Severity Index."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam","diagnosis.confirmatory_tests","management.first_line[0]"],"MS4":["pearls[0]","management.next_line[0]"]},"anki_refs":[],"sources":[{"title":"Diagnosis and Treatment of Adults with Community-acquired Pneumonia: An Official Clinical Practice Guideline of the ATS and IDSA (2019)"}]}'::jsonb),
  ('copd-exacerbation', 1, 'in_review', null, null, '{"name":"COPD exacerbation","aliases":["acute exacerbation of COPD","AECOPD"],"rotation":["IM","EM"],"epidemiology":{"who":"Adults with COPD, usually with a long smoking history","risk_factors":["viral respiratory infection","bacterial infection","air pollution","stopping inhalers"]},"pathophysiology":"Airway inflammation, usually triggered by infection, worsens airflow limitation and air trapping, raising the work of breathing and causing hypoxemia and sometimes hypercapnia.","timeline":{"onset":"Over days","course":"Most recover over 1 to 2 weeks; each exacerbation speeds the decline in lung function"},"key_findings":{"history":["worsening dyspnea","increased sputum volume","increased sputum purulence","cough"],"exam":["wheeze and prolonged expiration","accessory muscle use","pursed-lip breathing"],"labs":["arterial blood gas: hypercapnia and respiratory acidosis in severe cases"],"imaging":["chest X-ray to exclude pneumonia, pneumothorax or heart failure"]},"diagnosis":{"confirmatory_tests":["clinical diagnosis","arterial blood gas","chest X-ray"],"criteria":["acute worsening of dyspnea, cough or sputum beyond day-to-day variation"]},"management":{"first_line":["short-acting bronchodilators (albuterol with ipratropium)","systemic corticosteroids for 5 days","antibiotics when sputum purulence increases","controlled oxygen targeting saturation 88 to 92%"],"next_line":["noninvasive ventilation for hypercapnic respiratory acidosis","intubation if noninvasive ventilation fails"]},"complications":["hypercapnic respiratory failure","pneumothorax","death"],"confused_with":[{"script_id":"community-acquired-pneumonia","how_to_tell_apart":"Pneumonia adds fever and a new consolidation on chest X-ray; a COPD exacerbation has no new infiltrate."},{"script_id":"heart-failure-exacerbation","how_to_tell_apart":"Heart failure gives a raised JVP, leg edema, a high BNP and pulmonary edema on chest X-ray."},{"script_id":"asthma-exacerbation","how_to_tell_apart":"Asthma usually starts younger, often without a smoking history, and its airflow obstruction is largely reversible between attacks."}],"pearls":["Target oxygen saturation 88 to 92% in COPD; high-flow oxygen can worsen hypercapnia."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"Global Strategy for the Diagnosis, Management, and Prevention of COPD (GOLD 2025 Report)"}]}'::jsonb),
  ('decompensated-cirrhosis', 1, 'in_review', null, null, '{"name":"Decompensated cirrhosis","aliases":["cirrhosis","end-stage liver disease"],"rotation":["IM"],"epidemiology":{"who":"Adults with chronic liver disease","risk_factors":["alcohol-related liver disease","chronic hepatitis C","chronic hepatitis B","metabolic dysfunction-associated steatotic liver disease"]},"pathophysiology":"Chronic liver injury causes fibrosis and portal hypertension, leading to ascites, varices and loss of the liver''s synthetic and detoxifying function.","timeline":{"onset":"Develops over years; decompensation can be sudden","course":"Decompensation marks a sharp fall in survival; transplant is the cure"},"key_findings":{"history":["abdominal swelling","jaundice","confusion","vomiting blood or black stools"],"exam":["ascites","jaundice","spider angiomas","palmar erythema","asterixis"],"labs":["low albumin","prolonged INR","raised bilirubin","low platelets"],"imaging":["ultrasound: nodular liver, splenomegaly, ascites"]},"diagnosis":{"confirmatory_tests":["diagnostic paracentesis for new ascites or any admission with ascites","serum-ascites albumin gradient"],"criteria":["decompensation means ascites, variceal bleeding, hepatic encephalopathy or jaundice","a serum-ascites albumin gradient of 1.1 g/dL or more means portal hypertension"]},"management":{"first_line":["sodium restriction and diuretics (spironolactone with furosemide) for ascites","lactulose for hepatic encephalopathy","nonselective beta-blocker such as carvedilol to prevent variceal bleeding"],"next_line":["large-volume paracentesis with albumin for tense ascites","add rifaximin to lactulose","refer for liver transplant evaluation"]},"complications":["spontaneous bacterial peritonitis","hepatorenal syndrome","variceal bleeding","hepatic encephalopathy","hepatocellular carcinoma"],"confused_with":[],"pearls":["Spontaneous bacterial peritonitis is diagnosed by an ascitic neutrophil count of 250 cells/mm3 or more."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"AASLD Practice Guidance: Diagnosis, Evaluation, and Management of Ascites, Spontaneous Bacterial Peritonitis and Hepatorenal Syndrome (2021)"},{"title":"Baveno VII: Renewing consensus in portal hypertension (2022)"}]}'::jsonb),
  ('deep-vein-thrombosis', 1, 'in_review', null, null, '{"name":"Deep vein thrombosis","aliases":["DVT"],"rotation":["IM","EM","surgery"],"epidemiology":{"who":"Adults with risk factors for venous thromboembolism","risk_factors":["recent surgery","immobilization","active cancer","prior VTE","estrogen use or pregnancy","inherited thrombophilia"]},"pathophysiology":"Venous stasis, endothelial injury and hypercoagulability (Virchow''s triad) lead to thrombus in the deep veins, usually of the leg.","timeline":{"onset":"Over days","course":"Can embolize to the lungs; may leave post-thrombotic syndrome"},"key_findings":{"history":["unilateral leg swelling","calf pain"],"exam":["calf swelling more than 3 cm compared with the other leg","pitting edema of one leg","tenderness along the deep veins"],"labs":["raised D-dimer, useful to rule out DVT when pretest probability is low"],"imaging":["compression ultrasound showing a noncompressible vein"]},"diagnosis":{"confirmatory_tests":["compression ultrasound","D-dimer to rule out DVT when the Wells score is low"],"criteria":["the Wells score estimates pretest probability"]},"management":{"first_line":["anticoagulation with a direct oral anticoagulant such as apixaban or rivaroxaban for at least 3 months"],"next_line":["low-molecular-weight heparin in pregnancy","IVC filter only if anticoagulation is contraindicated"]},"complications":["pulmonary embolism","post-thrombotic syndrome","phlegmasia cerulea dolens"],"confused_with":[{"script_id":"cellulitis","how_to_tell_apart":"Cellulitis gives warm, red, tender skin with a spreading edge and often fever; DVT gives swelling and calf pain, and ultrasound shows a noncompressible vein."},{"script_id":"pulmonary-embolism","how_to_tell_apart":"PE adds dyspnea, pleuritic pain and hypoxemia; they are the same disease, so look for both."}],"pearls":["Virchow''s triad: venous stasis, endothelial injury and hypercoagulability."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"Antithrombotic Therapy for VTE Disease: Second Update of the CHEST Guideline and Expert Panel Report (2021)"}]}'::jsonb),
  ('diabetic-ketoacidosis', 1, 'in_review', null, null, '{"name":"Diabetic ketoacidosis","aliases":["DKA"],"rotation":["IM","EM"],"epidemiology":{"who":"Mostly people with type 1 diabetes, often as the first presentation; also type 2 diabetes under acute stress or on SGLT2 inhibitors","risk_factors":["infection","insulin omission","new-onset diabetes","SGLT2 inhibitors","myocardial infarction","pancreatitis"]},"pathophysiology":"Insulin deficiency plus excess counterregulatory hormones (glucagon, cortisol, catecholamines) drive lipolysis and hepatic ketogenesis, causing an anion gap metabolic acidosis. Hyperglycemia causes an osmotic diuresis with volume depletion and a total-body potassium deficit.","timeline":{"onset":"Develops over hours, usually less than 24 hours","course":"Resolves over about a day with fluids, insulin and potassium; can recur if the precipitant is not treated"},"key_findings":{"history":["polyuria and polydipsia","nausea and vomiting","abdominal pain"],"exam":["Kussmaul respirations (deep, rapid breathing)","fruity (acetone) breath","signs of volume depletion: tachycardia, dry mucous membranes"],"labs":["glucose usually above 250 mg/dL","anion gap metabolic acidosis","raised serum beta-hydroxybutyrate","serum potassium often normal or high despite a total-body deficit"],"imaging":[]},"diagnosis":{"confirmatory_tests":["serum beta-hydroxybutyrate","venous blood gas","basic metabolic panel with anion gap"],"criteria":["glucose of 200 mg/dL or more, or known diabetes","ketosis: beta-hydroxybutyrate of 3.0 mmol/L or more, or urine ketones 2+ or more","acidosis: pH below 7.3 and/or bicarbonate below 18 mEq/L"]},"management":{"first_line":["IV isotonic fluids","IV insulin infusion","potassium replacement"],"next_line":["add dextrose to the fluids when glucose falls below 250 mg/dL","bicarbonate only if pH is below 7.0","overlap subcutaneous basal insulin by 1 to 2 hours before stopping the infusion","treat the precipitant"]},"complications":["hypokalemia","hypoglycemia","cerebral edema, mainly in children","recurrence after stopping the infusion too early"],"confused_with":[{"script_id":"acute-pancreatitis","how_to_tell_apart":"DKA causes abdominal pain and can raise lipase, but the labs show an anion gap acidosis with high ketones, and the pain eases as the acidosis is corrected; in pancreatitis the pain persists and imaging shows an inflamed pancreas."},{"script_id":"hyperosmolar-hyperglycemic-state","how_to_tell_apart":"HHS has much higher glucose and osmolality with little or no ketosis or acidosis, and develops over days rather than hours."}],"pearls":["Check potassium before starting insulin: if it is below 3.5 mEq/L, replace it first and hold insulin, because insulin drives potassium into cells."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam[0]","management.first_line","diagnosis.criteria"],"MS4":["pearls[0]","management.next_line"]},"anki_refs":[],"sources":[{"title":"Hyperglycemic Crises in Adults With Diabetes: A Consensus Report (Diabetes Care, 2024)"}]}'::jsonb),
  ('heart-failure-exacerbation', 1, 'in_review', null, null, '{"name":"Acute decompensated heart failure","aliases":["heart failure exacerbation","ADHF","CHF exacerbation"],"rotation":["IM","EM"],"epidemiology":{"who":"Adults with known chronic heart failure, with reduced or preserved ejection fraction","risk_factors":["high salt intake","medication nonadherence","myocardial ischemia","atrial fibrillation","uncontrolled hypertension","infection","NSAIDs"]},"pathophysiology":"Worsening cardiac function or a precipitant raises left-sided filling pressures, causing pulmonary congestion, while sodium and water retention cause systemic venous congestion.","timeline":{"onset":"Usually over days, sometimes hours","course":"Most improve with diuresis over several days; each admission marks a worse long-term prognosis"},"key_findings":{"history":["worsening dyspnea","orthopnea","paroxysmal nocturnal dyspnea","weight gain","leg swelling"],"exam":["raised JVP","bibasilar crackles","S3 gallop","pitting edema"],"labs":["raised BNP or NT-proBNP","troponin may be mildly raised"],"imaging":["chest X-ray: pulmonary vascular congestion, interstitial edema, Kerley B lines, pleural effusions","echocardiogram to assess ejection fraction"]},"diagnosis":{"confirmatory_tests":["BNP or NT-proBNP","echocardiogram","chest X-ray"],"criteria":["clinical diagnosis: symptoms and signs of congestion, supported by a raised natriuretic peptide"]},"management":{"first_line":["IV loop diuretics such as furosemide","supplemental oxygen if hypoxemic","treat the precipitant"],"next_line":["add a thiazide-type diuretic such as metolazone if diuresis is inadequate","noninvasive ventilation for respiratory distress","vasodilators such as nitroglycerin if hypertensive","inotropes for low output with hypoperfusion"]},"complications":["cardiogenic shock","acute kidney injury","arrhythmias","hypokalemia from diuresis"],"confused_with":[{"script_id":"community-acquired-pneumonia","how_to_tell_apart":"Pneumonia usually brings fever, productive cough and a focal consolidation; heart failure gives bilateral crackles, a raised JVP, leg edema and a high BNP."},{"script_id":"copd-exacerbation","how_to_tell_apart":"A COPD exacerbation gives wheeze and more sputum in a smoker, without a raised JVP, leg edema or a high BNP."}],"pearls":["The first IV loop diuretic dose should equal or exceed the patient''s total daily oral dose."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.exam","diagnosis.confirmatory_tests","management.first_line[0]"],"MS4":["pearls[0]","management.next_line[0]"]},"anki_refs":[],"sources":[{"title":"2022 AHA/ACC/HFSA Guideline for the Management of Heart Failure"}]}'::jsonb),
  ('hyperkalemia', 1, 'in_review', null, null, '{"name":"Hyperkalemia","aliases":["high potassium"],"rotation":["IM","EM"],"epidemiology":{"who":"People with kidney disease or diabetes, or on drugs that raise potassium","risk_factors":["acute kidney injury","chronic kidney disease","ACE inhibitors or ARBs","potassium-sparing diuretics","rhabdomyolysis","adrenal insufficiency"]},"pathophysiology":"Reduced potassium excretion or a shift out of cells raises serum potassium, which depolarizes heart and muscle cells and slows cardiac conduction.","timeline":{"onset":"Acute or chronic","course":"Can cause fatal arrhythmias once ECG changes appear"},"key_findings":{"history":["often no symptoms","muscle weakness","palpitations"],"exam":["weakness","bradycardia"],"labs":["serum potassium above 5.5 mEq/L","pseudohyperkalemia from a hemolyzed sample","ECG: peaked T waves, then PR prolongation and a wide QRS, progressing to a sine wave"],"imaging":[]},"diagnosis":{"confirmatory_tests":["repeat serum potassium","12-lead ECG"],"criteria":["serum potassium above 5.5 mEq/L; severe at 6.5 mEq/L or above, or with ECG changes"]},"management":{"first_line":["IV calcium gluconate to stabilize the heart","insulin with glucose to shift potassium into cells","beta-2 agonist such as nebulized albuterol"],"next_line":["remove potassium: loop diuretics, potassium binders or dialysis","stop potassium-raising drugs"]},"complications":["ventricular fibrillation","asystole","bradyarrhythmias"],"confused_with":[],"pearls":["Calcium protects the heart within minutes but does not lower potassium; you still need to shift and remove it."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"Clinical Practice Guidelines: Treatment of Acute Hyperkalaemia in Adults (UK Kidney Association, 2023)"}]}'::jsonb),
  ('hyperosmolar-hyperglycemic-state', 1, 'in_review', null, null, '{"name":"Hyperosmolar hyperglycemic state","aliases":["HHS"],"rotation":["IM","EM"],"epidemiology":{"who":"Older adults with type 2 diabetes, often with limited access to water","risk_factors":["infection","insufficient insulin or missed medications","myocardial infarction","stroke","glucocorticoids","thiazide diuretics"]},"pathophysiology":"Relative insulin deficiency, with enough insulin to prevent ketogenesis, causes severe hyperglycemia, an osmotic diuresis, profound dehydration and hyperosmolality.","timeline":{"onset":"Develops over days to weeks","course":"Slower to correct than DKA, with a higher mortality"},"key_findings":{"history":["polyuria and polydipsia over days to weeks","weakness","confusion or drowsiness"],"exam":["severe dehydration","altered mental status, from lethargy to coma","focal neurologic signs or seizures in some"],"labs":["glucose usually above 600 mg/dL","effective serum osmolality above 300 mOsm/kg","pH 7.3 or higher and bicarbonate 15 mEq/L or higher","little or no ketonemia"],"imaging":[]},"diagnosis":{"confirmatory_tests":["serum glucose","calculated effective serum osmolality","serum beta-hydroxybutyrate to exclude significant ketosis"],"criteria":["glucose of 600 mg/dL or more","effective serum osmolality above 300 mOsm/kg (or total above 320)","pH 7.3 or higher, bicarbonate 15 mEq/L or higher, and no significant ketonemia"]},"management":{"first_line":["aggressive IV isotonic fluids","IV insulin infusion once fluids are running and potassium is at least 3.5 mEq/L","potassium replacement"],"next_line":["lower glucose, sodium and osmolality gradually to avoid cerebral edema","treat the precipitant","VTE prophylaxis"]},"complications":["cerebral edema from overly rapid correction","venous thromboembolism","rhabdomyolysis","acute kidney injury"],"confused_with":[{"script_id":"diabetic-ketoacidosis","how_to_tell_apart":"DKA has ketones and an anion gap acidosis and develops over hours; HHS has much higher glucose and osmolality, little or no ketosis, and develops over days."}],"pearls":["In HHS, fluids come first: insulin before adequate fluid replacement shifts water into cells and can worsen hypotension."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"Hyperglycemic Crises in Adults With Diabetes: A Consensus Report (Diabetes Care, 2024)"}]}'::jsonb),
  ('hyperthyroidism', 1, 'in_review', null, null, '{"name":"Hyperthyroidism","aliases":["thyrotoxicosis","Graves disease"],"rotation":["IM","FM"],"epidemiology":{"who":"Most often young to middle-aged women with Graves disease","risk_factors":["Graves disease","toxic multinodular goiter","toxic adenoma","thyroiditis","excess thyroid hormone intake","amiodarone"]},"pathophysiology":"Excess thyroid hormone, most often from TSH-receptor antibodies stimulating the gland in Graves disease, speeds metabolism and sympathetic activity.","timeline":{"onset":"Weeks to months","course":"Graves disease may remit after 12 to 18 months of antithyroid drugs"},"key_findings":{"history":["weight loss despite a good appetite","heat intolerance","palpitations","anxiety and tremor","frequent stools"],"exam":["tachycardia or atrial fibrillation","fine tremor","goiter","exophthalmos and pretibial myxedema in Graves disease"],"labs":["low TSH","high free T4 or T3","TSH-receptor antibodies in Graves disease"],"imaging":["radioactive iodine uptake scan: diffuse high uptake in Graves disease, low uptake in thyroiditis"]},"diagnosis":{"confirmatory_tests":["TSH","free T4","TSH-receptor antibodies or a radioactive iodine uptake scan to find the cause"],"criteria":["suppressed TSH with raised free T4 or T3"]},"management":{"first_line":["beta-blocker such as propranolol for symptoms","methimazole"],"next_line":["propylthiouracil in the first trimester of pregnancy and in thyroid storm","radioactive iodine ablation","thyroidectomy"]},"complications":["atrial fibrillation","thyroid storm","osteoporosis","agranulocytosis from antithyroid drugs"],"confused_with":[],"pearls":["Methimazole and propylthiouracil can cause agranulocytosis: stop the drug and check a white count if fever or a sore throat develops."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"2016 American Thyroid Association Guidelines for Diagnosis and Management of Hyperthyroidism and Other Causes of Thyrotoxicosis"}]}'::jsonb),
  ('hyponatremia', 1, 'in_review', null, null, '{"name":"Hyponatremia","aliases":["low sodium"],"rotation":["IM"],"epidemiology":{"who":"Older adults, hospitalized patients, and people on thiazides or SSRIs","risk_factors":["thiazide diuretics","SIADH","heart failure","cirrhosis","SSRIs","excess water intake"]},"pathophysiology":"Too much water relative to sodium, usually from ADH-driven water retention. After confirming low serum osmolality, it is classified by volume status.","timeline":{"onset":"Acute (under 48 hours) or chronic","course":"Chronic hyponatremia must be corrected slowly"},"key_findings":{"history":["nausea","headache","confusion","falls"],"exam":["assess volume status: dry, euvolemic or edematous","seizures or reduced consciousness when severe"],"labs":["serum sodium below 135 mEq/L","low serum osmolality in true (hypotonic) hyponatremia","urine osmolality above 100 mOsm/kg and urine sodium above 30 mEq/L in SIADH"],"imaging":[]},"diagnosis":{"confirmatory_tests":["serum osmolality","urine osmolality","urine sodium","volume status assessment"],"criteria":["serum sodium below 135 mEq/L; severe below 120 mEq/L"]},"management":{"first_line":["hypertonic 3% saline bolus for severe symptoms such as seizures","fluid restriction for SIADH","isotonic saline for hypovolemic hyponatremia","stop the offending drug"],"next_line":["limit correction to 8 mEq/L in 24 hours in chronic hyponatremia","urea or vaptans for refractory SIADH","treat heart failure or cirrhosis in hypervolemic hyponatremia"]},"complications":["seizures","cerebral edema","osmotic demyelination syndrome from overly rapid correction","falls and fractures"],"confused_with":[],"pearls":["Correcting chronic hyponatremia too fast causes osmotic demyelination syndrome; limit the rise to 8 mEq/L in 24 hours."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"Clinical practice guideline on diagnosis and treatment of hyponatraemia (ESE, ERA-EDTA and ESICM, 2014)"}]}'::jsonb),
  ('infective-endocarditis', 1, 'in_review', null, null, '{"name":"Infective endocarditis","aliases":["endocarditis"],"rotation":["IM"],"epidemiology":{"who":"People who inject drugs, and those with prosthetic valves, prior endocarditis or structural heart disease","risk_factors":["injection drug use","prosthetic heart valve","prior endocarditis","structural or congenital heart disease","indwelling intravascular devices","hemodialysis"]},"pathophysiology":"Bacteria, most often Staphylococcus aureus, seed a heart valve and form vegetations that destroy the valve and shed septic emboli.","timeline":{"onset":"Acute over days (S. aureus) or subacute over weeks (viridans streptococci)","course":"Fatal without treatment; many patients need surgery"},"key_findings":{"history":["fever","fatigue and weight loss in subacute disease","new heart failure symptoms"],"exam":["new regurgitant murmur","splinter hemorrhages","painless Janeway lesions on the palms and soles","painful Osler nodes on the fingers","Roth spots"],"labs":["persistently positive blood cultures","raised inflammatory markers","hematuria from glomerulonephritis"],"imaging":["echocardiogram showing a vegetation: transthoracic first, transesophageal if negative or with a prosthetic valve"]},"diagnosis":{"confirmatory_tests":["three sets of blood cultures before antibiotics","echocardiogram"],"criteria":["Duke criteria: typical organisms in blood cultures and evidence of endocardial involvement are the major criteria"]},"management":{"first_line":["empiric IV vancomycin after blood cultures","prolonged IV antibiotics (4 to 6 weeks) guided by culture results"],"next_line":["surgery for heart failure, uncontrolled infection, abscess, or large vegetations with embolism"]},"complications":["heart failure from valve destruction","septic emboli to the brain, lungs, spleen or kidneys","perivalvular abscess","glomerulonephritis"],"confused_with":[],"pearls":["Endocarditis in people who inject drugs often affects the tricuspid valve and causes septic pulmonary emboli."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"2023 ESC Guidelines for the management of endocarditis"},{"title":"The 2023 Duke-International Society for Cardiovascular Infectious Diseases Criteria for Infective Endocarditis"}]}'::jsonb),
  ('iron-deficiency-anemia', 1, 'in_review', null, null, '{"name":"Iron deficiency anemia","aliases":["IDA"],"rotation":["IM","FM","peds"],"epidemiology":{"who":"Menstruating and pregnant women, infants, and older adults with GI blood loss","risk_factors":["heavy menstrual bleeding","gastrointestinal blood loss","pregnancy","low dietary iron","celiac disease","bariatric surgery"]},"pathophysiology":"Blood loss or poor absorption depletes iron stores, limiting hemoglobin synthesis and producing small, pale red cells.","timeline":{"onset":"Weeks to months","course":"Hemoglobin rises about 1 to 2 g/dL over 2 to 3 weeks of replacement"},"key_findings":{"history":["fatigue","exertional dyspnea","pica, especially craving ice","restless legs"],"exam":["pallor","koilonychia (spoon nails)","angular cheilitis"],"labs":["microcytic anemia (low MCV)","low ferritin","high RDW","low transferrin saturation","high total iron-binding capacity"],"imaging":[]},"diagnosis":{"confirmatory_tests":["serum ferritin","complete blood count"],"criteria":["ferritin below 30 ng/mL confirms iron deficiency in most adults"]},"management":{"first_line":["oral iron, once daily or on alternate days","find and treat the cause of blood loss"],"next_line":["IV iron if oral iron fails or isn''t tolerated","colonoscopy and upper endoscopy in men and postmenopausal women"]},"complications":["heart failure from severe anemia","poor pregnancy outcomes"],"confused_with":[],"pearls":["Iron deficiency in a man or a postmenopausal woman is GI cancer until proven otherwise: scope both ends."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"AGA Clinical Practice Guidelines on the Gastrointestinal Evaluation of Iron Deficiency Anemia (2020)"}]}'::jsonb),
  ('nephritic-syndrome', 1, 'in_review', null, null, '{"name":"Nephritic syndrome","aliases":["acute glomerulonephritis"],"rotation":["IM","peds"],"epidemiology":{"who":"Children and adults; post-infectious glomerulonephritis is common in children, and IgA nephropathy is the most common glomerulonephritis worldwide","risk_factors":["post-streptococcal glomerulonephritis","IgA nephropathy","lupus nephritis","ANCA-associated vasculitis","anti-GBM disease","infective endocarditis"]},"pathophysiology":"Immune-mediated inflammation of the glomeruli damages the capillary walls, letting red cells into the urine and lowering filtration, which causes salt and water retention, hypertension and a rising creatinine.","timeline":{"onset":"Days to weeks","course":"Post-streptococcal disease usually resolves in children; rapidly progressive forms can cause kidney failure within weeks"},"key_findings":{"history":["cola-colored urine","reduced urine output","recent sore throat or skin infection"],"exam":["hypertension","periorbital or leg edema"],"labs":["hematuria with red blood cell casts and dysmorphic red cells","rising creatinine","proteinuria usually below 3.5 g/day","low complement C3 in post-streptococcal glomerulonephritis and lupus nephritis"],"imaging":[]},"diagnosis":{"confirmatory_tests":["urinalysis with microscopy for red blood cell casts","complement levels (C3 and C4)","serologies: ANCA, anti-GBM, ANA, ASO","kidney biopsy"],"criteria":["hematuria with red cell casts, hypertension, edema and reduced kidney function"]},"management":{"first_line":["supportive care","blood pressure control","loop diuretics and salt restriction for fluid overload","treat the underlying cause"],"next_line":["immunosuppression (steroids with cyclophosphamide or rituximab) for rapidly progressive disease such as ANCA vasculitis","plasma exchange for anti-GBM disease","dialysis for refractory fluid overload, hyperkalemia or uremia"]},"complications":["acute kidney injury","hypertensive emergency","pulmonary edema","progression to chronic kidney disease"],"confused_with":[{"script_id":"nephrotic-syndrome","how_to_tell_apart":"Nephrotic syndrome has heavy proteinuria above 3.5 g/day, low albumin and a bland urine sediment; nephritic syndrome has red blood cell casts, hypertension and a rising creatinine."}],"pearls":["IgA nephropathy causes hematuria within a few days of an upper respiratory infection, while post-streptococcal glomerulonephritis appears 1 to 3 weeks after a sore throat."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["key_findings.labs[0]","epidemiology.risk_factors","management.first_line"],"MS4":["pearls[0]","management.next_line[1]"]},"anki_refs":[],"sources":[{"title":"KDIGO 2021 Clinical Practice Guideline for the Management of Glomerular Diseases"}]}'::jsonb),
  ('nephrotic-syndrome', 1, 'in_review', null, null, '{"name":"Nephrotic syndrome","aliases":[],"rotation":["IM","peds"],"epidemiology":{"who":"Children, usually from minimal change disease, and adults, most often from membranous nephropathy, FSGS or diabetic kidney disease","risk_factors":["minimal change disease","focal segmental glomerulosclerosis","membranous nephropathy","diabetic nephropathy","amyloidosis","lupus nephritis"]},"pathophysiology":"Injury to the glomerular filtration barrier (the podocytes) lets large amounts of protein leak into the urine, causing low serum albumin, edema and a compensatory rise in hepatic lipoprotein synthesis. Urinary loss of anticoagulant proteins makes patients hypercoagulable.","timeline":{"onset":"Usually over weeks","course":"Minimal change disease often remits with steroids; other causes may progress to chronic kidney disease"},"key_findings":{"history":["swelling around the eyes and legs","foamy urine","weight gain"],"exam":["pitting edema","periorbital edema","ascites or pleural effusions"],"labs":["proteinuria above 3.5 g/day","serum albumin below 3 g/dL","hyperlipidemia","fatty casts and oval fat bodies in the urine"],"imaging":[]},"diagnosis":{"confirmatory_tests":["urine protein-to-creatinine ratio","24-hour urine protein","kidney biopsy to find the cause in adults"],"criteria":["proteinuria above 3.5 g/day with hypoalbuminemia and edema; hyperlipidemia is common"]},"management":{"first_line":["ACE inhibitor or ARB to reduce proteinuria","loop diuretics and salt restriction for edema","treat the underlying cause"],"next_line":["corticosteroids for minimal change disease","statin for persistent hyperlipidemia","anticoagulation for thrombosis"]},"complications":["renal vein thrombosis","deep vein thrombosis and pulmonary embolism","infection","acute kidney injury"],"confused_with":[{"script_id":"nephritic-syndrome","how_to_tell_apart":"Nephritic syndrome has hematuria with red blood cell casts, hypertension and a rising creatinine, with proteinuria usually below 3.5 g/day; nephrotic syndrome has heavy proteinuria above 3.5 g/day with a bland sediment."}],"pearls":["Urinary loss of antithrombin III makes nephrotic patients hypercoagulable; renal vein thrombosis is classic with membranous nephropathy."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.criteria[0]","epidemiology.risk_factors","management.first_line[0]"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"KDIGO 2021 Clinical Practice Guideline for the Management of Glomerular Diseases"}]}'::jsonb),
  ('pulmonary-embolism', 1, 'in_review', null, null, '{"name":"Pulmonary embolism","aliases":["PE"],"rotation":["IM","EM","surgery"],"epidemiology":{"who":"Adults with risk factors for venous thromboembolism","risk_factors":["recent surgery","immobilization","active cancer","prior VTE","estrogen use or pregnancy","inherited thrombophilia"]},"pathophysiology":"A thrombus, usually from the deep veins of the legs, lodges in the pulmonary arteries, causing ventilation-perfusion mismatch and hypoxemia; a large clot strains the right ventricle and can cause shock.","timeline":{"onset":"Sudden","course":"Most stable patients recover with anticoagulation; massive PE can cause sudden death"},"key_findings":{"history":["sudden dyspnea","pleuritic chest pain","hemoptysis","unilateral leg swelling"],"exam":["tachycardia","tachypnea","hypoxemia","clear lungs"],"labs":["raised D-dimer","raised troponin or BNP with right ventricular strain"],"imaging":["CT pulmonary angiography showing a filling defect","echocardiogram may show right ventricular dilation"]},"diagnosis":{"confirmatory_tests":["CT pulmonary angiography","V/Q scan if CT contrast is contraindicated"],"criteria":["use the Wells score to estimate pretest probability","with low pretest probability, a negative D-dimer rules out PE"]},"management":{"first_line":["anticoagulation, preferably a direct oral anticoagulant such as apixaban or rivaroxaban"],"next_line":["systemic thrombolysis for high-risk PE with hypotension","catheter-directed therapy or surgical embolectomy if thrombolysis fails or is contraindicated","IVC filter only if anticoagulation is contraindicated"]},"complications":["right heart failure","obstructive shock","pulmonary infarction","chronic thromboembolic pulmonary hypertension"],"confused_with":[{"script_id":"community-acquired-pneumonia","how_to_tell_apart":"Pneumonia usually brings fever, productive cough, focal crackles and a consolidation on chest X-ray; PE more often has clear lungs and a near-normal X-ray despite hypoxemia."},{"script_id":"deep-vein-thrombosis","how_to_tell_apart":"DVT is the usual source of PE: look for unilateral leg swelling and calf pain, and confirm with compression ultrasound."}],"pearls":["The most common ECG finding in PE is sinus tachycardia; the classic S1Q3T3 pattern is uncommon."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["epidemiology.risk_factors","diagnosis.confirmatory_tests[0]","management.first_line[0]"],"MS4":["pearls[0]","management.next_line[0]","diagnosis.criteria[1]"]},"anki_refs":[],"sources":[{"title":"2019 ESC Guidelines for the diagnosis and management of acute pulmonary embolism"},{"title":"Antithrombotic Therapy for VTE Disease: Second Update of the CHEST Guideline and Expert Panel Report (2021)"}]}'::jsonb),
  ('septic-shock', 1, 'in_review', null, null, '{"name":"Sepsis and septic shock","aliases":["sepsis","septic shock"],"rotation":["IM","EM"],"epidemiology":{"who":"Anyone with an infection; highest risk in older adults and the immunocompromised","risk_factors":["pneumonia","urinary tract infection","intra-abdominal infection","skin and soft tissue infection","indwelling lines or catheters"]},"pathophysiology":"A dysregulated host response to infection causes vasodilation, capillary leak and organ dysfunction.","timeline":{"onset":"Hours","course":"Mortality rises with each hour of delayed antibiotics in septic shock"},"key_findings":{"history":["fever or chills","confusion","symptoms of the source infection"],"exam":["hypotension","tachycardia","tachypnea","altered mental status","warm or mottled skin"],"labs":["lactate above 2 mmol/L","signs of organ dysfunction: rising creatinine or bilirubin, low platelets"],"imaging":["imaging to find the source, guided by symptoms"]},"diagnosis":{"confirmatory_tests":["blood cultures before antibiotics","serum lactate","SOFA score for organ dysfunction"],"criteria":["sepsis: suspected infection with an acute rise of 2 or more SOFA points","septic shock: vasopressors needed to keep MAP at 65 mmHg or more, with lactate above 2 mmol/L despite fluids"]},"management":{"first_line":["broad-spectrum antibiotics within 1 hour","30 mL/kg IV crystalloid for hypotension or lactate of 4 mmol/L or more","norepinephrine if hypotension persists"],"next_line":["source control","add vasopressin for rising norepinephrine needs","hydrocortisone for refractory shock"]},"complications":["multi-organ failure","ARDS","acute kidney injury","disseminated intravascular coagulation","death"],"confused_with":[{"script_id":"adrenal-insufficiency","how_to_tell_apart":"Adrenal crisis also causes shock that doesn''t respond to fluids, often with hyponatremia, hyperkalemia and hypoglycemia; suspect it in anyone on long-term steroids."}],"pearls":["Target a mean arterial pressure of at least 65 mmHg; norepinephrine is the first-line vasopressor."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2021"},{"title":"The Third International Consensus Definitions for Sepsis and Septic Shock (Sepsis-3, 2016)"}]}'::jsonb),
  ('upper-gi-bleeding', 1, 'in_review', null, null, '{"name":"Upper gastrointestinal bleeding","aliases":["upper GI bleed","UGIB"],"rotation":["IM","EM","surgery"],"epidemiology":{"who":"Adults; peptic ulcer disease is the most common cause","risk_factors":["peptic ulcer disease","esophageal varices","NSAIDs","Helicobacter pylori","anticoagulants","Mallory-Weiss tear"]},"pathophysiology":"Bleeding above the ligament of Treitz, most often from a peptic ulcer eroding a vessel, or from varices in portal hypertension.","timeline":{"onset":"Acute","course":"Most bleeds stop on their own; rebleeding raises mortality"},"key_findings":{"history":["hematemesis or coffee-ground vomit","melena","lightheadedness or syncope","NSAID or alcohol use"],"exam":["tachycardia and hypotension","signs of chronic liver disease in variceal bleeding"],"labs":["falling hemoglobin","raised BUN-to-creatinine ratio from digested blood"],"imaging":[]},"diagnosis":{"confirmatory_tests":["upper endoscopy within 24 hours"],"criteria":["the Glasgow-Blatchford score identifies low-risk patients for outpatient care"]},"management":{"first_line":["two large-bore IV lines and fluid resuscitation","transfuse to a hemoglobin of 7 g/dL (8 with cardiovascular disease)","IV proton pump inhibitor","upper endoscopy within 24 hours"],"next_line":["for varices: octreotide and antibiotics (ceftriaxone) before endoscopy, then band ligation","test for and treat Helicobacter pylori"]},"complications":["hemorrhagic shock","rebleeding","death"],"confused_with":[],"pearls":["In suspected variceal bleeding, give octreotide and antibiotics before endoscopy; antibiotics reduce infection and death."],"difficulty_tiers":{"MS1-2":["pathophysiology"],"MS3":["diagnosis.confirmatory_tests","management.first_line"],"MS4":["pearls[0]"]},"anki_refs":[],"sources":[{"title":"ACG Clinical Guideline: Upper Gastrointestinal and Ulcer Bleeding (2021)"},{"title":"Baveno VII: Renewing consensus in portal hypertension (2022)"}]}'::jsonb);
